"""Offline dashboard template; camera and risk state are supplied by Flask."""
DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Safesight · Safety monitor</title><style>
:root{--paper:#edf1f4;--panel:#fff;--ink:#142632;--muted:#506473;--line:#c8d3db;--blue:#176b90;--low:#237454;--medium:#926b08;--high:#b85216;--critical:#a93036}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 'Segoe UI',sans-serif}button,a{touch-action:manipulation}button{font:inherit;cursor:pointer;min-height:44px;padding:8px 18px;border:1px solid var(--line);border-radius:6px;background:var(--panel);color:var(--ink)}button:hover{background:#e2ebf1}button:focus-visible,a:focus-visible{outline:3px solid var(--blue);outline-offset:4px}a{color:var(--blue)}
header{background:var(--panel);border-bottom:1px solid var(--line)}.top{max-width:1460px;margin:auto;padding:22px 32px;display:flex;align-items:center;gap:16px}.brand{display:flex;align-items:center;gap:12px}.brand svg{color:var(--blue)}h1{margin:0;font:600 30px/1.1 Bahnschrift,'Segoe UI',sans-serif;letter-spacing:-.6px}.subtitle{font-size:14px;color:var(--muted);margin-top:5px}.top-right{margin-left:auto;display:flex;align-items:center;gap:18px}.mode{font-weight:600;padding:6px 12px;border-radius:4px;background:#e4edf3;color:#23516c;font-size:14px}
main{max-width:1460px;margin:auto;padding:26px 32px 40px}.message{padding:13px 18px;background:#fff4d7;border:1px solid #d5ad50;border-radius:6px;margin-bottom:20px;color:#674b0a}.message.error{background:#fae6e7;border-color:#cf8d91;color:#7f252b}.hidden{display:none!important}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}h2{font:600 22px/1.2 Bahnschrift,'Segoe UI',sans-serif;margin:0}.source-status{font-size:14px;color:var(--muted)}.monitor{display:grid;grid-template-columns:minmax(0,1fr) 315px;gap:22px}.video-panel,.risk-panel,.inputs,.events{background:var(--panel);border:1px solid var(--line);border-radius:8px;overflow:hidden}.video-screen{aspect-ratio:16/9;background:#253b49;position:relative;display:grid;place-items:center;color:#d3e1e9}.video-screen img{width:100%;height:100%;object-fit:contain;position:absolute}.video-placeholder{text-align:center;max-width:36ch;padding:24px}.video-footer{padding:13px 18px;display:flex;gap:26px;flex-wrap:wrap;border-top:1px solid var(--line);font-size:14px}.video-footer strong{font-variant-numeric:tabular-nums}.risk-panel{padding:24px;display:flex;flex-direction:column;--state:var(--muted)}.risk-panel[data-band=Low]{--state:var(--low)}.risk-panel[data-band=Medium]{--state:var(--medium)}.risk-panel[data-band=High]{--state:var(--high)}.risk-panel[data-band=Critical]{--state:var(--critical)}.risk-label{font-size:16px;font-weight:600}.score{display:flex;align-items:baseline;gap:6px;white-space:nowrap;font:600 92px/1.15 Bahnschrift,'Segoe UI',sans-serif;color:var(--state);font-variant-numeric:tabular-nums;letter-spacing:-4px;margin-top:18px}.score small{flex-shrink:0;white-space:nowrap;font:400 20px 'Segoe UI',sans-serif;color:var(--muted);letter-spacing:0}.band{font-size:26px;font-weight:650;color:var(--state);margin:0 0 18px}.track{height:10px;background:#e4eaf0;border-radius:5px;overflow:hidden}.fill{height:100%;background:var(--state);width:0}.cause{color:var(--muted);font-size:15px;margin-top:18px}.alert-state{font-weight:600;color:var(--state);margin-top:auto;padding-top:18px}.inputs{margin-top:22px;padding:20px 22px}.input-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;margin-top:18px}.input-name{font-size:14px;color:var(--muted);margin-bottom:5px}.input-value{font:600 23px Bahnschrift,'Segoe UI',sans-serif;font-variant-numeric:tabular-nums}.input-bar{height:5px;background:#e3eaf0;margin-top:10px}.input-bar span{height:100%;background:var(--blue);display:block;width:0}.events{margin-top:22px}.events-head{padding:20px 22px;display:flex;align-items:center;gap:16px}.events-head span{color:var(--muted);font-size:14px;margin-left:auto}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:660px;font-size:14px;text-align:left}th{font-weight:600;color:var(--muted);background:#f4f7f9}th,td{padding:13px 22px;border-top:1px solid var(--line);vertical-align:top}td:nth-child(1){white-space:nowrap;font-variant-numeric:tabular-nums}.event-band{font-weight:650}.event-band[data-band=High]{color:var(--high)}.event-band[data-band=Critical]{color:var(--critical)}.empty{padding:24px;color:var(--muted)}footer{font-size:13px;color:var(--muted);margin-top:20px;display:flex;gap:20px;justify-content:space-between}
@media(max-width:900px){.monitor{grid-template-columns:minmax(0,1fr) 255px}.risk-panel{padding:18px}.score{font-size:82px}.input-grid{grid-template-columns:repeat(2,1fr)}.top,main{padding-left:20px;padding-right:20px}.mode{max-width:185px}}
@media(max-width:640px){.top{flex-wrap:wrap;padding-top:16px;padding-bottom:16px}.top-right{width:100%;margin-left:0;justify-content:space-between}.monitor{grid-template-columns:1fr}.risk-panel{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.risk-label{grid-column:1/-1}.score{grid-row:2/5;margin-top:8px;font-size:68px;flex-direction:column;gap:0;letter-spacing:-2px;line-height:1.1}.band{margin:12px 0 8px;font-size:24px}.track{align-self:center}.cause{grid-column:1/-1;margin:12px 0}.alert-state{grid-column:1/-1;padding-top:0}.heading{align-items:flex-start;gap:10px;flex-direction:column}.video-footer{gap:14px}.events-head{flex-wrap:wrap}.events-head span{margin-left:0}th,td{padding:12px 16px}footer{flex-direction:column;gap:5px}main{padding-top:18px}.input-grid{gap:20px}.score small{font-size:17px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body>
<header><div class="top"><div class="brand"><svg width="38" height="38" viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M20 4 34 10v12c0 7-8 12-14 15C14 34 6 29 6 22V10L20 4Z" stroke="currentColor" stroke-width="2.5"/><path d="M11 20s4-6 9-6 9 6 9 6-4 6-9 6-9-6-9-6Z" stroke="currentColor" stroke-width="2"/><circle cx="20" cy="20" r="3" fill="currentColor"/></svg><div><h1>Safesight</h1><div class="subtitle">Safety monitoring station</div></div></div><div class="top-right"><span id="mode" class="mode">Connecting</span><button id="pause" type="button" aria-pressed="false">Pause display</button></div></div></header>
<main><div id="message" class="message" role="status">Connecting to the monitoring station…</div>
<div class="heading"><h2>Camera overview</h2><span class="source-status" id="source-status">Waiting for the first frame</span></div>
<div class="monitor"><section class="video-panel" aria-label="Camera feed"><div class="video-screen"><div id="video-placeholder" class="video-placeholder">Waiting for a camera frame.</div><img id="feed" alt="Annotated safety monitoring feed" hidden></div><div class="video-footer"><span><span id="fps-label">Processing</span>: <strong id="fps">—</strong></span><span><span id="latency-label">Decision latency</span>: <strong id="latency">—</strong></span><span>People: <strong id="people">—</strong></span><span>In zone: <strong id="crowd">—</strong></span></div></section>
<section class="risk-panel" id="risk-panel" aria-label="Current risk"><div class="risk-label">Safety risk score</div><div class="score"><span id="score">—</span><small> / 100</small></div><p class="band" id="band">Waiting</p><div class="track" aria-hidden="true"><div class="fill" id="risk-fill"></div></div><p class="cause" id="cause">Risk appears once monitoring starts.</p><div class="alert-state" id="alert-state" aria-live="polite">No current reading</div></section></div>
<section class="inputs" aria-label="Risk inputs"><h2>What drives the score</h2><div class="input-grid"><div><div class="input-name">PPE violations</div><div class="input-value" id="ppe_load">—</div><div class="input-bar"><span id="ppe_load-bar"></span></div></div><div><div class="input-name">Zone pressure</div><div class="input-value" id="zone_pressure">—</div><div class="input-bar"><span id="zone_pressure-bar"></span></div></div><div><div class="input-name">Hazard proximity</div><div class="input-value" id="proximity">—</div><div class="input-bar"><span id="proximity-bar"></span></div></div><div><div class="input-name">Fire / smoke evidence</div><div class="input-value" id="fire_evidence">—</div><div class="input-bar"><span id="fire_evidence-bar"></span></div></div></div></section>
<section class="events" aria-label="Recent events"><div class="events-head"><h2>Recent alerts</h2><span id="event-note">Last 10 confirmed events</span></div><div class="table-scroll" tabindex="0" role="region" aria-label="Recent alerts table; scroll horizontally on small screens"><table><thead><tr><th scope="col">Time</th><th scope="col">Level</th><th scope="col">Score</th><th scope="col">Cause</th><th scope="col">Snapshot</th></tr></thead><tbody id="events"></tbody></table></div><div class="empty" id="empty">No confirmed alerts yet. Events appear after High or Critical risk persists for one second.</div></section>
<footer><span id="footer-note">Camera and detector status will appear here.</span><span id="updated">No update received</span></footer></main>
<script>
const $=id=>document.getElementById(id);let paused=false,lastState=null,feedActive=false;
const inputs=['ppe_load','zone_pressure','proximity','fire_evidence'];
function stream(active){if(active===feedActive)return;feedActive=active;if(active){$('feed').src='/video_feed?t='+Date.now();$('feed').hidden=false;$('video-placeholder').classList.add('hidden')}else{$('feed').removeAttribute('src');$('feed').hidden=true;$('video-placeholder').classList.remove('hidden');$('video-placeholder').textContent=paused?'Display paused. Monitoring and alerts continue.':'Camera preview unavailable.'}}
function unavailable(text){$('risk-panel').removeAttribute('data-band');$('score').textContent='—';$('band').textContent='Unavailable';$('risk-fill').style.width='0';$('alert-state').textContent=text;$('cause').textContent=text;for(const key of inputs){$(key).textContent='—';$(key+'-bar').style.width='0'}}
function message(text,error=false){$('message').textContent=text||'';$('message').classList.toggle('hidden',!text);$('message').classList.toggle('error',error)}
function render(s){lastState=s;const demo=s.mode==='demo';$('mode').textContent=demo?'Demo simulation':'Camera monitoring';$('fps-label').textContent=demo?'Simulation cadence':'Processing';$('latency-label').textContent=demo?'Simulation step':'Decision latency';$('event-note').textContent=demo?'Simulation events only':'Last 10 confirmed events';$('footer-note').textContent=demo?'Simulated scene. No camera or AI detections.':'Fire detection is an early-warning alert layer.';
const fresh=s.updated_at&&Date.now()-Date.parse(s.updated_at)<3500;const active=s.status==='active'&&fresh;
$('source-status').textContent=s.status==='active'?(demo?'Scripted scene sequence':'Camera connected'):s.status;
if(!active){unavailable(s.error||'Waiting for fresh monitoring data');message(s.error||'Monitoring data is not current. Check the camera or monitoring process.',true)}else{message(demo?'Demo simulation — alerts and snapshots below come from a scripted scene.':(s.latched?'Critical alert latched. Clearing requires three continuous seconds below High.':null));$('risk-panel').dataset.band=s.band;$('score').textContent=s.score.toFixed(1);$('band').textContent=s.band;$('risk-fill').style.width=s.score+'%';$('cause').textContent=s.cause;$('alert-state').textContent=s.latched?'Critical alert latched':s.pending?'Confirming alert…':(['High','Critical'].includes(s.output_level)?'Alert active':'No active alert');for(const key of inputs){$(key).textContent=Math.round(s[key]*100)+'%';$(key+'-bar').style.width=s[key]*100+'%'}}
$('fps').textContent=s.fps===null?'—':s.fps.toFixed(1)+' fps';$('latency').textContent=s.latency_ms===null?'—':s.latency_ms.toFixed(1)+' ms';$('people').textContent=s.people??'—';$('crowd').textContent=s.crowd_count??'—';$('updated').textContent=s.updated_at?'Updated '+new Date(s.updated_at).toLocaleTimeString():'No update received';
const body=$('events');body.replaceChildren();for(const event of s.events){const tr=document.createElement('tr');const values=[new Date(event.timestamp).toLocaleTimeString(),event.band,event.score.toFixed(1),event.cause];values.forEach((value,i)=>{const td=document.createElement('td');td.textContent=value;if(i===1){td.className='event-band';td.dataset.band=event.band}tr.appendChild(td)});const td=document.createElement('td');if(event.snapshot){const a=document.createElement('a');a.href='/snapshots/'+encodeURIComponent(event.snapshot);a.textContent='View image';a.target='_blank';a.rel='noopener';a.setAttribute('aria-label','View snapshot from '+new Date(event.timestamp).toLocaleTimeString());td.appendChild(a)}else td.textContent='Unavailable';tr.appendChild(td);body.appendChild(tr)}$('empty').classList.toggle('hidden',s.events.length>0);stream(!paused&&!document.hidden&&active&&s.has_frame)}
async function poll(){if(!paused&&!document.hidden){const request=new AbortController();const timeout=setTimeout(()=>request.abort(),2500);try{const response=await fetch('/api/state',{cache:'no-store',signal:request.signal});if(!response.ok)throw Error('state');render(await response.json())}catch{unavailable('Connection lost');message('Connection to the monitoring station was lost.',true);stream(false)}finally{clearTimeout(timeout)}}setTimeout(poll,750)}
$('pause').addEventListener('click',()=>{paused=!paused;$('pause').textContent=paused?'Resume display':'Pause display';$('pause').setAttribute('aria-pressed',String(paused));if(paused){stream(false);message('Display paused. Monitoring, alerts, and event recording continue.')}else if(lastState)render(lastState)});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stream(false);else if(!paused&&lastState)render(lastState)});poll();
</script></body></html>'''
